## Why This Is Asked
Tests automation of security incident response in a complex SAP on AWS environment, focusing on real-world tooling and cross-account controls.

## Key Concepts
- RFC anomaly detection via CloudWatch and GuardDuty
- Cross-account IAM roles with MFA-protected STS elevation
- Automated network isolation through security group modifications
- Secrets rotation for SAP credentials in AWS Secrets Manager
- Step Functions orchestration for workflow and audit trails

## Code Example
```javascript
{
  "Comment": "SAP incident response state machine",
  "StartAt": "DetectAnomaly",
  "States": {
    "DetectAnomaly": {
      "Type": "Choice",
      "Choices": [
        {
          "Variable": "$.alert_type",
          "StringEquals": "RFC_ANOMALY",
          "Next": "AssumeRemediationRole"
        }
      ],
      "Default": "LogAndDismiss"
    },
    "AssumeRemediationRole": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:...:function:assume-role-with-mfa",
      "Next": "IsolateHost"
    },
    "IsolateHost": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:...:function:isolate-sap-host",
      "Next": "RotateCredentials"
    },
    "RotateCredentials": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:...:function:rotate-sap-secrets",
      "Next": "NotifyAndLog"
    },
    "NotifyAndLog": {
      "Type": "Task",
      "Resource": "arn:aws:lambda:...:function:notify-and-log",
      "End": true
    },
    "LogAndDismiss": {
      "Type": "Pass",
      "End": true
    }
  }
}
```

## Minimal IaC Sketch (Terraform)
```hcl
resource "aws_sfn_state_machine" "sap_incident_response" {
  name     = "sap-incident-response"
  role_arn = aws_iam_role.stepfunctions_role.arn
  definition = file("${path.module}/state_machine.json")
}

resource "aws_iam_role" "cross_account_remediation" {
  name = "sap-remediation-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = { AWS = "arn:aws:iam::123456789:role/sap-incident-response-role" },
      Action = "sts:AssumeRole",
      Condition = { Bool = { "aws:MultiFactorAuthPresent" = true } }
    }]
  })
}

resource "aws_security_group_rule" "sap_isolation" {
  count = 1
  type        = "ingress"
  from_port   = 0
  to_port     = 0
  protocol    = "-1"
  description = "Emergency isolation"
  source_security_group_id = aws_security_group.sap_management.id
}
```

## Why This Is Asked

Assesses ability to design scalable, auditable cross-account access that bridges SAP authorizations with AWS IAM, while using JIT and MFA in a multi-region, multi-account setup. Tests integration points across IAM, SCPs, SSO, auditing, and basic IaC.

## Key Concepts

- Cross-account trust and least privilege
- SCPs and IAM role mappings to SAP authorizations
- Just‑In‑Time elevation with AWS SSO and MFA
- Auditing: CloudTrail, Config, Central logging
- Minimal IaC for trust role and VPC endpoint service

## Code Example

```javascript
// Minimal Terraform-like snippet for cross-account trust role (pseudo)
provider "aws" { alias = "shared" }
resource "aws_iam_role" "sap_operator_trust" {
  name = "sap-operator-cross-account"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      {
        Effect = "Allow",
        Principal = { AWS = ["arn:aws:iam::111111111111:root"] },
        Action = "sts:AssumeRole",
        Condition = { StringEquals = { "sts:ExternalId" = "sap-access" } }
      }
    ]
  })
}

// Per‑BU session policy (inline for example)
resource "aws_iam_role_policy" "sap_operator_policy" {
  name = "sap-operator-permission"
  role = aws_iam_role.sap_operator_trust.name
  policy = jsonencode({
    Version = "2012-10-17",
    Statement = [
      { Effect = "Allow", Action = ["ec2:Describe*"], Resource = "*" },
      { Effect = "Allow", Action = ["sap:*"], Resource = "*" }
    ]
  })
}

// VPC Endpoint Service placeholder
resource "aws_vpc_endpoint_service" "sap_endpoints" {
  acceptance_required = true
  network_load_balancer_arns = [aws_lb.sap_nlb.arn]
}
```

